create table public.project28_config(id boolean primary key default true check(id),released boolean not null default false,opens_at timestamptz not null default '2026-10-25 00:00:00+05:30',content jsonb not null default '{}'::jsonb check(octet_length(content::text)<250000));
create table public.project28_progress(user_id uuid primary key references auth.users(id),data jsonb not null default '{}'::jsonb check(octet_length(data::text)<20000));
create table public.project28_memories(id uuid primary key default gen_random_uuid(),author uuid not null default auth.uid() references auth.users(id),caption text not null check(length(caption)<4000),path text,created_at timestamptz not null default now());
create table public.project28_capsules(id uuid primary key default gen_random_uuid(),author uuid not null default auth.uid() references auth.users(id),title text not null check(length(title)<200),body text not null check(length(body)<20000),unlocks_at timestamptz not null check(unlocks_at>now()),created_at timestamptz not null default now());
alter table public.project28_config enable row level security;alter table public.project28_progress enable row level security;alter table public.project28_memories enable row level security;alter table public.project28_capsules enable row level security;
insert into public.project28_config(id) values(true);
create policy p28_config_read on public.project28_config for select to authenticated using(exists(select 1 from public.universe_members where user_id=auth.uid() and (slot=1 or (released and now()>=opens_at))));
create policy p28_config_update on public.project28_config for update to authenticated using(exists(select 1 from public.universe_members where user_id=auth.uid() and slot=1)) with check(exists(select 1 from public.universe_members where user_id=auth.uid() and slot=1) and (not released or exists(select 1 from public.project28_progress where user_id=auth.uid() and data->>'previewed'='true')));
create policy p28_progress_read on public.project28_progress for select to authenticated using(user_id=auth.uid() or exists(select 1 from public.universe_members where user_id=auth.uid() and slot=1));
create policy p28_progress_insert on public.project28_progress for insert to authenticated with check(user_id=auth.uid() and exists(select 1 from public.universe_members where user_id=auth.uid()));
create policy p28_progress_update on public.project28_progress for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid() and exists(select 1 from public.universe_members where user_id=auth.uid()));
create policy p28_memories_read on public.project28_memories for select to authenticated using(exists(select 1 from public.project28_config));
create policy p28_memories_insert on public.project28_memories for insert to authenticated with check(author=auth.uid() and exists(select 1 from public.project28_config));
create policy p28_capsules_insert on public.project28_capsules for insert to authenticated with check(author=auth.uid() and exists(select 1 from public.project28_config));
grant select,update on public.project28_config to authenticated;grant select,insert,update on public.project28_progress to authenticated;grant select,insert on public.project28_memories to authenticated;grant insert on public.project28_capsules to authenticated;
revoke all on public.project28_capsules from anon;
create function public.project28_capsule_list() returns jsonb language plpgsql security definer set search_path='' as $$begin if not exists(select 1 from public.universe_members where user_id=auth.uid()) or not exists(select 1 from public.project28_config where exists(select 1 from public.universe_members where user_id=auth.uid() and slot=1) or (released and now()>=opens_at)) then raise exception 'Not available';end if;return coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'author',author,'unlocks_at',unlocks_at,'body',case when now()>=unlocks_at then body else null end) order by unlocks_at) from public.project28_capsules),'[]'::jsonb);end$$;
revoke all on function public.project28_capsule_list() from public,anon;grant execute on function public.project28_capsule_list() to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('project28','project28',false,10485760,array['image/jpeg','image/png','image/webp','audio/mp4','audio/mpeg','audio/ogg','audio/wav','audio/webm']);
create policy p28_assets_read on storage.objects for select to authenticated using(bucket_id='project28' and exists(select 1 from public.project28_config));
create policy p28_assets_insert on storage.objects for insert to authenticated with check(bucket_id='project28' and (storage.foldername(name))[1]=auth.uid()::text and exists(select 1 from public.project28_config));
